function configurePortfolio(baseId, portfolioTable, historyTable, timestamp) {
  if (typeof baseId !== "string" || !/^app[A-Za-z0-9]{14}$/.test(baseId))
    throw new Error("Enter your Airtable base ID");
  if (
    !portfolioTable?.trim() ||
    !historyTable?.trim() ||
    portfolioTable.trim() === historyTable.trim()
  ) {
    throw new Error("Choose separate Airtable portfolio and history tables");
  }
  const time = new Date(timestamp);
  if (!Number.isFinite(time.getTime())) throw new Error("A valid schedule timestamp is required");
  time.setUTCMinutes(0, 0, 0);
  const hour = time.toISOString();
  return {
    baseId,
    portfolioTable: portfolioTable.trim(),
    historyTable: historyTable.trim(),
    hour,
    key: "portfolio:" + hour,
  };
}

const config = configurePortfolio(
  "appYYYYYYYYYYYYYY",
  "Portfolio",
  "Portfolio Value",
  $input.first().json.timestamp,
);
const prefix = "https://api.airtable.com/v0/" + config.baseId + "/";
return [
  {
    json: {
      ...config,
      positionUrl: prefix + encodeURIComponent(config.portfolioTable),
      historyUrl: prefix + encodeURIComponent(config.historyTable),
    },
  },
];

function readPortfolioPage(state, page, offset, values) {
  if (!Array.isArray(page)) throw new Error("Airtable returned an invalid portfolio page");
  const before = state ?? { rows: [], offsets: [] };
  if (
    offset !== null &&
    (typeof offset !== "string" || !offset || before.offsets.includes(offset))
  ) {
    throw new Error("Airtable returned a malformed or repeated offset");
  }
  const ids = new Set(before.rows.map((row) => row.id));
  const snapshot = [];
  for (const record of page) {
    const id = record?.id;
    const coinId = record?.fields?.Symbol;
    if (typeof id !== "string" || !/^rec[A-Za-z0-9]+$/.test(id) || ids.has(id)) {
      throw new Error("Airtable returned a missing or duplicate record ID");
    }
    if (typeof coinId !== "string" || !/^[a-z0-9][a-z0-9._-]*$/.test(coinId)) {
      throw new Error("Enter a CoinGecko API coin ID in Symbol for " + id);
    }
    ids.add(id);
    const row = { id, coinId };
    if (values) {
      row.price = record.fields["Present Price"] ?? null;
      row.value = record.fields["Present Value"] ?? null;
    }
    snapshot.push(row);
  }
  return {
    rows: before.rows.concat(snapshot),
    offsets: offset === null ? before.offsets : [...before.offsets, offset],
  };
}

function airtableListResult(body) {
  if (!Array.isArray(body?.records) || (body.offset != null && typeof body.offset !== "string")) {
    throw new Error("Airtable returned an invalid portfolio page");
  }
  return { rows: body.records, offset: body.offset ?? null };
}

let state = null;
let offset;
for (const {
  json: { body, statusCode },
} of $input.all()) {
  if (statusCode !== 200) throw new Error("Airtable portfolio read failed with HTTP " + statusCode);
  const page = airtableListResult(body);
  offset = page.offset;
  state = readPortfolioPage(state, page.rows, offset, false);
}
if (offset !== null || state === null)
  throw new Error("Airtable portfolio pagination did not finish");
function splitBatches(items, size) {
  const batches = [];
  for (let start = 0; start < items.length; start += size)
    batches.push(items.slice(start, start + size));
  return batches;
}

const ids = [...new Set(state.rows.map((row) => row.coinId))];
return [
  { json: { portfolio: state.rows, groups: splitBatches(ids, 100), empty: ids.length === 0 } },
];

function takeQuotes(ids, prices) {
  if (prices === null || typeof prices !== "object" || Array.isArray(prices)) {
    throw new Error("CoinGecko returned an invalid price result");
  }
  return Object.fromEntries(
    ids.map((id) => {
      const dollar = Object.hasOwn(prices, id) ? prices[id]?.usd : undefined;
      if (!Number.isFinite(dollar) || dollar < 0)
        throw new Error("Missing or invalid CoinGecko USD price for " + id);
      return [id, dollar];
    }),
  );
}

function recordsToUpdate(rows, prices) {
  return rows.map(({ id, coinId }) => ({ id, fields: { "Present Price": prices[coinId] } }));
}

function splitBatches(items, size) {
  const batches = [];
  for (let start = 0; start < items.length; start += size)
    batches.push(items.slice(start, start + size));
  return batches;
}

const expected = $("Collect portfolio and group CoinGecko IDs").first().json;
const input = $input.all();
if (input.length !== expected.groups.length)
  throw new Error("CoinGecko responses did not cover the requested groups");
const prices = {};
for (const [index, item] of input.entries()) {
  if (item.json.statusCode !== 200) throw new Error("CoinGecko did not confirm the price request");
  const groupIndex = item.pairedItem?.item ?? index;
  Object.assign(prices, takeQuotes(expected.groups[groupIndex], item.json.body));
}
if (Object.keys(prices).length !== new Set(expected.portfolio.map((row) => row.coinId)).size)
  throw new Error("CoinGecko prices are incomplete");
return [
  { json: { prices, batches: splitBatches(recordsToUpdate(expected.portfolio, prices), 10) } },
];

const state = $input.first().json;
if (Object.keys(state).length === 0) return [{ json: { fresh: true } }];
if (state.hour_key !== $("Set Airtable tables").first().json.key || state.status !== "done") {
  throw new Error(
    "Airtable writes for " +
      $("Set Airtable tables").first().json.hour +
      " are pending. Check both tables before retrying.",
  );
}
return [{ json: { fresh: false } }];

const reservation = $input.first().json;
if (
  reservation.hour_key !== $("Set Airtable tables").first().json.key ||
  reservation.status !== "pending"
)
  throw new Error("The hourly checkpoint was not confirmed");
return $("Validate all quotes and plan price updates")
  .first()
  .json.batches.map((records) => ({ json: { records } }));

function confirmPrices(records, requested) {
  if (!Array.isArray(records) || records.length !== requested.length) {
    throw new Error("Airtable did not confirm all updated portfolio rows");
  }
  const prices = new Map(requested.map((row) => [row.id, row.fields["Present Price"]]));
  for (const row of records) {
    if (!prices.has(row?.id) || row.fields?.["Present Price"] !== prices.get(row.id)) {
      throw new Error("Airtable returned a different record ID or price for this update");
    }
    prices.delete(row.id);
  }
}

const item = $input.first().json;
const request = $("Update price batches in order").itemMatching(0).json;
confirmPrices(item.body?.records, request.records);
return [{ json: { updated: request.records.length } }];

const updated = $input.all().reduce((sum, item) => sum + item.json.updated, 0);
if (updated !== $("Collect portfolio and group CoinGecko IDs").first().json.portfolio.length)
  throw new Error("Not all portfolio rows were updated");
return [{ json: { updated } }];

