function airtableListResult(body) {
  if (!Array.isArray(body?.records) || (body.offset != null && typeof body.offset !== "string")) {
    throw new Error("Airtable returned an invalid portfolio page");
  }
  return { rows: body.records, offset: body.offset ?? null };
}

let state = null;
let offset;
for (const {
  json: { body, statusCode },
} of $input.all()) {
  if (statusCode !== 200) throw new Error("Airtable portfolio read failed with HTTP " + statusCode);
  const page = airtableListResult(body);
  offset = page.offset;
  state = readPortfolioPage(state, page.rows, offset, true);
}
if (offset !== null || state === null)
  throw new Error("Airtable portfolio pagination did not finish");
function totalPortfolio(initial, completed, prices) {
  if (completed.length !== initial.length)
    throw new Error("The Airtable portfolio changed during pricing");
  const expected = new Map(initial.map((row) => [row.id, row.coinId]));
  let value = 0;
  for (const row of completed) {
    if (expected.get(row.id) !== row.coinId || row.price !== prices[row.coinId]) {
      throw new Error("The Airtable portfolio changed during pricing");
    }
    if (!Number.isFinite(row.value)) throw new Error("Present Value must be numeric for " + row.id);
    value += row.value;
  }
  if (!Number.isFinite(value)) throw new Error("The portfolio total is outside the numeric range");
  return value;
}

const total = totalPortfolio(
  $("Collect portfolio and group CoinGecko IDs").first().json.portfolio,
  state.rows,
  $("Validate all quotes and plan price updates").first().json.prices,
);
return [{ json: { total, records: [{ fields: { "Portfolio Value (US$)": total } }] } }];

function confirmSnapshot(records, total) {
  if (
    !Array.isArray(records) ||
    records.length !== 1 ||
    !/^rec[A-Za-z0-9]+$/.test(records[0]?.id ?? "") ||
    records[0].fields?.["Portfolio Value (US$)"] !== total
  ) {
    throw new Error("Airtable did not confirm the portfolio history append");
  }
  return records[0].id;
}

const item = $input.first().json;
const total = $("Sum Airtable calculated values").first().json.total;
const airtableId = confirmSnapshot(item.body?.records, total);
return [
  { json: { state: "done", hour: $("Set Airtable tables").first().json.hour, total, airtableId } },
];

const checkpoint = $input.first().json;
if (
  checkpoint.hour_key !== $("Set Airtable tables").first().json.key ||
  checkpoint.status !== "done"
)
  throw new Error("The completed checkpoint was not confirmed");
return [{ json: $("Confirm the appended history row").first().json }];
